SELECT payload,payload::text FROM (SELECT coalesce(jsonb_agg(jsonb_build_object('raw',to_jsonb(p),'identity',to_jsonb(pg_identify_object('pg_policy'::regclass,p.oid,0)),'table',to_jsonb(pg_identify_object('pg_class'::regclass,p.polrelid,0)),'roles',(SELECT jsonb_agg(jsonb_build_object('oid',x,'name',CASE WHEN x=0 THEN 'PUBLIC' ELSE pg_get_userbyid(x) END) ORDER BY x) FROM unnest(p.polroles) x),'using',pg_get_expr(p.polqual,p.polrelid,false),'check',pg_get_expr(p.polwithcheck,p.polrelid,false)) ORDER BY p.oid),'[]'::jsonb) AS payload FROM pg_policy p WHERE p.polrelid IN (SELECT oid FROM pg_class WHERE relnamespace='public'::regnamespace UNION SELECT reltoastrelid FROM pg_class WHERE relnamespace='public'::regnamespace AND reltoastrelid<>0 UNION SELECT i.indexrelid FROM pg_index i JOIN pg_class c ON c.reltoastrelid=i.indrelid WHERE c.relnamespace='public'::regnamespace)) AS capture